/**
 * AG UI event reducer and ChatView API for streaming chat transcripts.
 * Framework-free; attaches window.ChatView / globalThis.ChatView.
 */
(function () {
  "use strict";

  function CreateChatState() {
    return {
      messages: new Map(),
      messageOrder: [],
      openTextMessages: new Set(),
      openToolCalls: new Map(),
      openReasoning: new Set(),
      runs: new Map(),
      activeSteps: new Map(),
      caughtUp: false,
      eventCount: 0,
      status: { kind: "loading", message: null },
    };
  }

  function SynthesizeId(state, eventType) {
    return `${eventType}:${state.eventCount}`;
  }

  function CreateChatMessage(id, role, options) {
    const opts = options || {};
    return {
      id: id,
      role: role,
      content: opts.content != null ? String(opts.content) : "",
      toolCalls: opts.toolCalls ? opts.toolCalls.slice() : [],
      toolCallId: opts.toolCallId != null ? opts.toolCallId : null,
      isStreaming: opts.isStreaming === true,
      timestamp: opts.timestamp != null ? opts.timestamp : null,
      activityType: opts.activityType != null ? opts.activityType : null,
    };
  }

  function AddMessage(state, message) {
    if (!state.messages.has(message.id)) {
      state.messageOrder.push(message.id);
    }
    state.messages.set(message.id, message);
    return message;
  }

  function AppendSystemMessage(state, content, id) {
    const messageId = id || SynthesizeId(state, "system");
    return AddMessage(
      state,
      CreateChatMessage(messageId, "system", { content: content })
    );
  }

  function FindToolCallInfo(state, toolCallId) {
    for (const messageId of state.messageOrder) {
      const message = state.messages.get(messageId);
      if (!message || message.role !== "assistant") {
        continue;
      }
      for (const toolCall of message.toolCalls) {
        if (toolCall.id === toolCallId) {
          return toolCall;
        }
      }
    }
    return null;
  }

  function RecomputeStatus(state) {
    if (state.status.kind === "error") {
      return;
    }
    if (!state.caughtUp) {
      state.status = { kind: "loading", message: null };
      return;
    }
    let hasRunning = false;
    for (const run of state.runs.values()) {
      if (run.status === "running") {
        hasRunning = true;
        break;
      }
    }
    if (hasRunning) {
      state.status = { kind: "live", message: null };
    } else {
      state.status = { kind: "complete", message: null };
    }
  }

  function CloseOpenStreams(state) {
    for (const messageId of Array.from(state.openTextMessages)) {
      const message = state.messages.get(messageId);
      if (message) {
        message.isStreaming = false;
      }
      state.openTextMessages.delete(messageId);
    }

    for (const toolCallId of Array.from(state.openToolCalls.keys())) {
      const openTool = state.openToolCalls.get(toolCallId);
      const toolInfo = FindToolCallInfo(state, toolCallId);
      if (toolInfo) {
        toolInfo.isOpen = false;
      }
      state.openToolCalls.delete(toolCallId);
      if (openTool) {
        openTool.argsBuffer = toolInfo ? toolInfo.args : openTool.argsBuffer;
      }
    }

    for (const messageId of Array.from(state.openReasoning)) {
      const message = state.messages.get(messageId);
      if (message) {
        message.isStreaming = false;
      }
      state.openReasoning.delete(messageId);
    }
  }

  function SnapshotMessageToChatMessage(snapshotMessage) {
    const role = snapshotMessage.role || "activity";
    const message = CreateChatMessage(String(snapshotMessage.id), role, {
      content:
        snapshotMessage.content != null ? String(snapshotMessage.content) : "",
      timestamp: snapshotMessage.timestamp != null ? snapshotMessage.timestamp : null,
      activityType:
        snapshotMessage.activityType != null
          ? snapshotMessage.activityType
          : null,
      toolCallId:
        snapshotMessage.toolCallId != null ? snapshotMessage.toolCallId : null,
    });

    if (Array.isArray(snapshotMessage.toolCalls)) {
      message.toolCalls = snapshotMessage.toolCalls.map(function (toolCall) {
        return {
          id: String(toolCall.id || toolCall.toolCallId || ""),
          name: String(toolCall.name || toolCall.toolCallName || ""),
          args: toolCall.arguments != null ? String(toolCall.arguments) : toolCall.args != null ? String(toolCall.args) : "",
          result: toolCall.result != null ? String(toolCall.result) : null,
          isOpen: false,
        };
      });
    }

    return message;
  }

  function ParseActivityContent(message) {
    if (!message || !message.content) {
      return {};
    }
    try {
      const parsed = JSON.parse(message.content);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return parsed;
      }
    } catch (_error) {
      //
    }
    return { text: message.content };
  }

  function StringifyActivityContent(value) {
    if (typeof value === "string") {
      return value;
    }
    try {
      return JSON.stringify(value);
    } catch (_error) {
      return String(value);
    }
  }

  function DecodeJsonPointerSegment(segment) {
    return segment.replace(/~1/g, "/").replace(/~0/g, "~");
  }

  function ParseJsonPointer(path) {
    if (typeof path !== "string" || path === "" || path === "/") {
      return [];
    }
    if (path.charAt(0) !== "/") {
      return null;
    }
    return path
      .slice(1)
      .split("/")
      .map(DecodeJsonPointerSegment);
  }

  function ResolvePatchParent(root, tokens) {
    if (!tokens || tokens.length === 0) {
      return { parent: null, key: null, valid: false };
    }
    let current = root;
    for (let index = 0; index < tokens.length - 1; index += 1) {
      const token = tokens[index];
      if (current == null || typeof current !== "object") {
        return { parent: null, key: null, valid: false };
      }
      current = current[token];
    }
    const lastToken = tokens[tokens.length - 1];
    if (current == null || typeof current !== "object") {
      return { parent: null, key: null, valid: false };
    }
    return { parent: current, key: lastToken, valid: true };
  }

  function ApplyJsonPatch(document, patch) {
    if (!Array.isArray(patch)) {
      return null;
    }

    let nextDocument;
    try {
      nextDocument = JSON.parse(JSON.stringify(document));
    } catch (_error) {
      return null;
    }

    for (const operation of patch) {
      if (!operation || typeof operation !== "object") {
        return null;
      }

      const op = operation.op;
      const pathTokens = ParseJsonPointer(operation.path);
      if (pathTokens === null) {
        return null;
      }

      if (op === "add" || op === "replace") {
        if (pathTokens.length === 0) {
          if (op === "replace") {
            nextDocument = operation.value;
          } else {
            return null;
          }
          continue;
        }

        const resolved = ResolvePatchParent(nextDocument, pathTokens);
        if (!resolved.valid) {
          return null;
        }

        if (Array.isArray(resolved.parent) && resolved.key === "-") {
          if (op !== "add") {
            return null;
          }
          resolved.parent.push(operation.value);
        } else {
          resolved.parent[resolved.key] = operation.value;
        }
      } else if (op === "remove") {
        if (pathTokens.length === 0) {
          return null;
        }
        const resolved = ResolvePatchParent(nextDocument, pathTokens);
        if (!resolved.valid) {
          return null;
        }
        if (Array.isArray(resolved.parent)) {
          const index = Number(resolved.key);
          if (!Number.isInteger(index) || index < 0 || index >= resolved.parent.length) {
            return null;
          }
          resolved.parent.splice(index, 1);
        } else {
          delete resolved.parent[resolved.key];
        }
      } else {
        return null;
      }
    }

    return nextDocument;
  }

  function CustomDisplayText(event) {
    if (event.name === "provider.text") {
      const value = event.value;
      if (value && typeof value === "object") {
        if (value.text != null) {
          return String(value.text);
        }
      }
      if (event.text != null) {
        return String(event.text);
      }
      return "";
    }
    return String(event.name || "custom");
  }

  function ReduceAguiEvent(state, event) {
    if (!event || typeof event !== "object") {
      return state;
    }

    state.eventCount += 1;
    const eventType = event.type;

    switch (eventType) {
      case "RUN_STARTED": {
        const runId = event.runId ? String(event.runId) : SynthesizeId(state, "RUN_STARTED");
        state.runs.set(runId, {
          runId: runId,
          threadId: event.threadId != null ? String(event.threadId) : runId,
          status: "running",
        });
        RecomputeStatus(state);
        break;
      }

      case "RUN_FINISHED": {
        const runId = event.runId ? String(event.runId) : null;
        if (runId && state.runs.has(runId)) {
          const run = state.runs.get(runId);
          run.status = "finished";
        }
        CloseOpenStreams(state);
        RecomputeStatus(state);
        break;
      }

      case "RUN_ERROR": {
        const runId = event.runId ? String(event.runId) : null;
        if (runId && state.runs.has(runId)) {
          const run = state.runs.get(runId);
          run.status = "error";
        }
        const errorText = event.message != null ? String(event.message) : "Run error";
        AppendSystemMessage(
          state,
          errorText,
          runId ? `error:${runId}` : SynthesizeId(state, "RUN_ERROR")
        );
        state.status = { kind: "error", message: errorText };
        break;
      }

      case "STEP_STARTED": {
        const stepName = event.stepName ? String(event.stepName) : SynthesizeId(state, "STEP_STARTED");
        state.activeSteps.set(stepName, {
          stepName: stepName,
          startTimestamp: event.timestamp != null ? event.timestamp : null,
        });
        break;
      }

      case "STEP_FINISHED": {
        const stepName = event.stepName ? String(event.stepName) : null;
        if (stepName) {
          state.activeSteps.delete(stepName);
        }
        break;
      }

      case "TEXT_MESSAGE_START": {
        const messageId = event.messageId
          ? String(event.messageId)
          : SynthesizeId(state, "TEXT_MESSAGE_START");
        const role = event.role ? String(event.role) : "assistant";
        AddMessage(
          state,
          CreateChatMessage(messageId, role, {
            isStreaming: true,
            timestamp: event.timestamp != null ? event.timestamp : null,
          })
        );
        state.openTextMessages.add(messageId);
        break;
      }

import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import vm from "node:vm";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const aguiChatPath = path.resolve(__dirname, "../src/agui-chat.js");

function LoadChatView(WebSocketClass) {
  const source = fs.readFileSync(aguiChatPath, "utf8");
  const context = {
    console,
    setTimeout,
    clearTimeout,
    WebSocket: WebSocketClass || class FakeWebSocket {
      constructor(url) {
        this.url = url;
        this.readyState = 0;
        this.CONNECTING = 0;
        this.OPEN = 1;
        this.CLOSING = 2;
        this.CLOSED = 3;
      }

      addEventListener() {}

      removeEventListener() {}

      close() {
        this.readyState = 3;
      }
    },
  };
  context.globalThis = context;
  context.window = context;
  vm.createContext(context);
  vm.runInContext(source, context);
  return context.ChatView;
}

const ChatView = LoadChatView();
const { createChatState, reduceAguiEvent, applyServerMessage } = ChatView._test;

function ReduceAll(state, events) {
  for (const event of events) {
    reduceAguiEvent(state, event);
  }
  return state;
}

function MessageContent(state, messageId) {
  return state.messages.get(messageId)?.content;
}

test("simple text message lifecycle", () => {
  const state = createChatState();
  const messageId = "msg-1";

  ReduceAll(state, [
    { type: "TEXT_MESSAGE_START", messageId, role: "assistant" },
    { type: "TEXT_MESSAGE_CONTENT", messageId, delta: "Hello " },
    { type: "TEXT_MESSAGE_CONTENT", messageId, delta: "world" },
    { type: "TEXT_MESSAGE_END", messageId },
  ]);

  const message = state.messages.get(messageId);
  assert.equal(message.role, "assistant");
  assert.equal(message.content, "Hello world");
  assert.equal(message.isStreaming, false);
  assert.equal(state.openTextMessages.size, 0);
  assert.equal(state.messageOrder.length, 1);
  assert.equal(state.messageOrder[0], messageId);
});

test("tool call lifecycle", () => {
  const state = createChatState();
  const parentId = "assistant-1";
  const toolCallId = "tool-1";

  ReduceAll(state, [
    { type: "TEXT_MESSAGE_START", messageId: parentId, role: "assistant" },
    { type: "TEXT_MESSAGE_END", messageId: parentId },
    {
      type: "TOOL_CALL_START",
      toolCallId,
      toolCallName: "grep",
      parentMessageId: parentId,
    },
    { type: "TOOL_CALL_ARGS", toolCallId, delta: '{"pattern":' },
    { type: "TOOL_CALL_ARGS", toolCallId, delta: '"foo"}' },
    {
      type: "TOOL_CALL_RESULT",
      toolCallId,
      messageId: `${toolCallId}:result`,
      content: "match line",
      role: "tool",
    },
    { type: "TOOL_CALL_END", toolCallId },
  ]);

  const parent = state.messages.get(parentId);
  assert.equal(parent.toolCalls.length, 1);
  assert.equal(parent.toolCalls[0].args, '{"pattern":"foo"}');
  assert.equal(parent.toolCalls[0].result, "match line");
  assert.equal(parent.toolCalls[0].isOpen, false);
  assert.equal(state.openToolCalls.size, 0);

  const toolMessage = state.messages.get(`${toolCallId}:result`);
  assert.equal(toolMessage.role, "tool");
  assert.equal(toolMessage.content, "match line");
  assert.equal(toolMessage.toolCallId, toolCallId);
});

test("reasoning lifecycle", () => {
  const state = createChatState();
  const phaseId = "reason-phase";
  const messageId = "reason-msg";

  ReduceAll(state, [
    { type: "REASONING_START", messageId: phaseId },
    { type: "REASONING_MESSAGE_START", messageId, role: "reasoning" },
    { type: "REASONING_MESSAGE_CONTENT", messageId, delta: "Thinking" },
    { type: "REASONING_MESSAGE_CONTENT", messageId, delta: " hard" },
    { type: "REASONING_MESSAGE_END", messageId },
    { type: "REASONING_END", messageId: phaseId },
  ]);

  const message = state.messages.get(messageId);
  assert.equal(message.role, "reasoning");
  assert.equal(message.content, "Thinking hard");
  assert.equal(message.isStreaming, false);
  assert.equal(state.openReasoning.size, 0);
});

test("run lifecycle and caught_up status", () => {
  const state = createChatState();
  const runId = "run-1";

  ReduceAll(state, [
    { type: "RUN_STARTED", runId, threadId: "thread-1" },
    { type: "TEXT_MESSAGE_START", messageId: "m1", role: "user" },
    { type: "TEXT_MESSAGE_CONTENT", messageId: "m1", delta: "hi" },
  ]);

  assert.equal(state.runs.get(runId).status, "running");
  assert.equal(state.status.kind, "loading");
  assert.equal(state.openTextMessages.has("m1"), true);

  applyServerMessage(state, { type: "caught_up" });
  assert.equal(state.caughtUp, true);
  assert.equal(state.status.kind, "live");

  ReduceAll(state, [
    { type: "TEXT_MESSAGE_END", messageId: "m1" },
    { type: "RUN_FINISHED", runId, threadId: "thread-1" },
  ]);

  assert.equal(state.runs.get(runId).status, "finished");
  assert.equal(state.openTextMessages.size, 0);
  assert.equal(state.status.kind, "complete");
});

test("RUN_ERROR creates system message and error status", () => {
  const state = createChatState();
  ReduceAll(state, [
    { type: "RUN_STARTED", runId: "run-err", threadId: "thread-1" },
    { type: "RUN_ERROR", runId: "run-err", message: "Harness failed" },
  ]);

  assert.equal(state.runs.get("run-err").status, "error");
  assert.equal(state.status.kind, "error");
  assert.equal(state.status.message, "Harness failed");

  const systemMessage = state.messages.get("error:run-err");
  assert.equal(systemMessage.role, "system");
  assert.equal(systemMessage.content, "Harness failed");
});

test("CUSTOM provider text, generic CUSTOM, and RAW", () => {
  const state = createChatState();

  ReduceAll(state, [
    {
      type: "CUSTOM",
      name: "provider.text",
      value: { text: "provider says hi" },
    },
    {
      type: "CUSTOM",
      name: "claude.system",
      value: { type: "system" },
    },
    {
      type: "RAW",
      source: "cursor",
      event: { event_kind: "unknown" },
    },
  ]);

  const providerMessage = state.messageOrder
    .map((id) => state.messages.get(id))
    .find((message) => message.activityType === "provider.text");
  assert.equal(providerMessage.content, "provider says hi");

  const genericCustom = state.messageOrder
    .map((id) => state.messages.get(id))
    .find((message) => message.activityType === "claude.system");
  assert.equal(genericCustom.content, "claude.system");

  const rawMessage = state.messageOrder
    .map((id) => state.messages.get(id))
    .find((message) => message.activityType === "cursor");
  assert.equal(rawMessage.content, "unrecognized event");
});

test("ACTIVITY_SNAPSHOT replacement and ACTIVITY_DELTA patching", () => {
  const state = createChatState();
  const messageId = "activity-1";

  ReduceAll(state, [
    {
      type: "ACTIVITY_SNAPSHOT",
      messageId,
      activityType: "codex.file_change",
      content: { path: "a.txt", status: "pending" },
    },
  ]);

  assert.equal(
    JSON.parse(state.messages.get(messageId).content).path,
    "a.txt"
  );

  ReduceAll(state, [
    {
      type: "ACTIVITY_DELTA",
      messageId,
      activityType: "codex.file_change",
      patch: [{ op: "replace", path: "/status", value: "done" }],
    },
  ]);

  assert.equal(
    JSON.parse(state.messages.get(messageId).content).status,
    "done"
  );

  ReduceAll(state, [
    {
      type: "ACTIVITY_SNAPSHOT",
      messageId,
      activityType: "codex.file_change",
      content: { path: "b.txt" },
      replace: true,
    },
  ]);

  assert.equal(
    JSON.parse(state.messages.get(messageId).content).path,
    "b.txt"
  );

  const beforeInvalidPatch = state.messages.get(messageId).content;
  ReduceAll(state, [
    {
      type: "ACTIVITY_DELTA",
      messageId,
      activityType: "codex.file_change",
      patch: [{ op: "move", path: "/status", from: "/missing" }],
    },
  ]);
  assert.equal(state.messages.get(messageId).content, beforeInvalidPatch);
});

test("MESSAGES_SNAPSHOT resets prior messages", () => {
  const state = createChatState();

  ReduceAll(state, [
    { type: "TEXT_MESSAGE_START", messageId: "old", role: "user" },
    { type: "TEXT_MESSAGE_CONTENT", messageId: "old", delta: "gone" },
    { type: "TEXT_MESSAGE_END", messageId: "old" },
    {
      type: "MESSAGES_SNAPSHOT",
      messages: [
        { id: "new-1", role: "assistant", content: "fresh start" },
        { id: "new-2", role: "user", content: "hello" },
      ],
    },
  ]);

  assert.equal(state.messages.has("old"), false);
  assert.equal(state.messageOrder.length, 2);
  assert.equal(state.messageOrder[0], "new-1");
  assert.equal(state.messageOrder[1], "new-2");
  assert.equal(MessageContent(state, "new-1"), "fresh start");
  assert.equal(state.openTextMessages.size, 0);
  assert.equal(state.openToolCalls.size, 0);
  assert.equal(state.openReasoning.size, 0);
});

test("no-op and unknown events do not alter visible transcript unexpectedly", () => {
  const state = createChatState();

  ReduceAll(state, [
    { type: "TEXT_MESSAGE_START", messageId: "keep", role: "assistant" },
    { type: "TEXT_MESSAGE_CONTENT", messageId: "keep", delta: "stable" },
    { type: "TEXT_MESSAGE_END", messageId: "keep" },
  ]);

  const before = {
    messageOrder: state.messageOrder.slice(),
    content: MessageContent(state, "keep"),
    eventCount: state.eventCount,
  };

  ReduceAll(state, [
    { type: "STATE_SNAPSHOT", snapshot: { internal: true } },
    { type: "STATE_DELTA", delta: [{ op: "add", path: "/x", value: 1 }] },
    {
      type: "REASONING_ENCRYPTED_VALUE",
      entityId: "keep",
      encryptedValue: "secret",
    },
    { type: "TOTALLY_UNKNOWN" },
  ]);

  assert.deepEqual(state.messageOrder, before.messageOrder);
  assert.equal(MessageContent(state, "keep"), before.content);
  assert.equal(state.eventCount, before.eventCount + 4);
});

test("applyServerMessage handles events, caught_up, error, and unknown types", () => {
  const state = createChatState();

  applyServerMessage(state, {
    type: "events",
    events: [
      { type: "TEXT_MESSAGE_START", messageId: "srv-1", role: "user" },
      { type: "TEXT_MESSAGE_CONTENT", messageId: "srv-1", delta: "from server" },
      { type: "TEXT_MESSAGE_END", messageId: "srv-1" },
    ],
  });
  assert.equal(MessageContent(state, "srv-1"), "from server");
  assert.equal(state.eventCount, 3);

  applyServerMessage(state, { type: "caught_up" });
  assert.equal(state.caughtUp, true);
  assert.equal(state.status.kind, "complete");

  applyServerMessage(state, { type: "error", message: "stream failed" });
  assert.equal(state.status.kind, "error");
  assert.equal(
    [...state.messages.values()].some(
      (message) => message.role === "system" && message.content === "stream failed"
    ),
    true
  );

  const countBeforeUnknown = state.eventCount;
  applyServerMessage(state, { type: "ping" });
  assert.equal(state.eventCount, countBeforeUnknown);
});

test("golden reducer replay from representative converted JSONL sequence", () => {
  const goldenEvents = [
    {
      type: "RUN_STARTED",
      threadId: "provider-1",
      runId: "test-thread:step:1",
      timestamp: 1735689600000,
    },
    {
      type: "TEXT_MESSAGE_START",
      messageId: "test-thread:step:1:seq:2:prompt",
      role: "user",
      timestamp: 1735689600000,
    },
    {
      type: "TEXT_MESSAGE_CONTENT",
      messageId: "test-thread:step:1:seq:2:prompt",
      delta: "hello",
      timestamp: 1735689600000,
    },
    {
      type: "TEXT_MESSAGE_END",
      messageId: "test-thread:step:1:seq:2:prompt",
      timestamp: 1735689600000,
    },
    {
      type: "RUN_FINISHED",
      threadId: "provider-1",
      runId: "test-thread:step:1",
      timestamp: 1735689601000,
    },
  ];

  const state = createChatState();
  applyServerMessage(state, { type: "events", events: goldenEvents });
  applyServerMessage(state, { type: "caught_up" });

  assert.equal(state.eventCount, goldenEvents.length);
  assert.equal(state.caughtUp, true);
  assert.equal(state.status.kind, "complete");
  assert.equal(state.runs.get("test-thread:step:1").status, "finished");
  assert.equal(state.messageOrder.length, 1);
